describe("Session 269 GUARD — heading content that LOOKS like a block token and must stay a heading", () => {
  // The R4 gate reads the heading's RAW content and declines the line where pandoc's inline parser
  // would refuse a token. Every row below is a shape where the token is NEUTRALISED and quarto
  // renders a real heading, so a containment test over the raw line would DELETE it — the cardinal
  // sin. Each expectation is a `quarto render --to html --no-execute` (quarto 1.7.33 / pandoc 3.6.3)
  // of these exact bytes, `scratchpad/s269/probes/verify/` and `b_html_form/`, re-run firsthand.
  const names = (lines: string[]) =>
    findHeadings(lines.join("\n") + "\n").map((h) => `h${h.level}:${h.text}`);
  const probe = (...body: string[]) => ["---", "title: probe", "engine: markdown", "---", "", ...body];
  const kept = (line: string) => names(probe(line, "", "## Tail"));

  it("G1: a block tag inside an INLINE CODE SPAN is documentation, not a tag (`verify/v22-section-in-code`)", () => {
    expect(kept("### T `<section>`")).toEqual(["h3:T `<section>`", "h2:Tail"]);
    expect(kept("### T `\\maketitle`")).toEqual(["h3:T `\\maketitle`", "h2:Tail"]);
  });

  it("G2: a BACKSLASH-ESCAPED `<` is literal text, and the model already un-escapes it (`verify/v23-escaped-lt`)", () => {
    expect(kept("### T \\<section>")).toEqual(["h3:T <section>", "h2:Tail"]);
  });

  it("G3: `\\\\` is an escaped BACKSLASH, so what follows is prose and not a macro (`verify/v24-double-backslash`)", () => {
    expect(kept("### T \\\\maketitle")).toEqual(["h3:T \\maketitle", "h2:Tail"]);
  });

  it("G4: an HTML ENTITY spelling never reaches the tag scan (`b_html_form/b32-entity`)", () => {
    expect(kept("### T &lt;section&gt;")).toEqual(["h3:T &lt;section&gt;", "h2:Tail"]);
  });

  it("G5: MATH protects absolutely (`verify/v20-macro-in-math`, `b_html_form/b38-math`)", () => {
    expect(kept("### T $\\maketitle$")).toEqual(["h3:T $\\maketitle$", "h2:Tail"]);
    expect(kept("### T $<section>$")).toEqual(["h3:T $<section>$", "h2:Tail"]);
  });

  it("G6: a link DESTINATION, LABEL and TITLE are all consumed whole (`verify/v11-link-title`, `v19-macro-in-brackets`, `b_html_form/b33-link-url`)", () => {
    expect(kept("### T [a](http://x/<section>)")).toEqual(["h3:T [a](http://x/<section>)", "h2:Tail"]);
    expect(kept("### T [\\maketitle](u)")).toEqual(["h3:T [\\maketitle](u)", "h2:Tail"]);
    expect(kept('### T [a](http://x "<section>")')).toEqual(['h3:T [a](http://x "<section>")', "h2:Tail"]);
  });

  it("G7: ANY bracketed inline content neutralises — an inline note and a bracketed span (`verify/v10-inline-note`, `v18-bracket-span`)", () => {
    expect(kept("### T ^[<section>]")).toEqual(["h3:T ^[<section>]", "h2:Tail"]);
    // ⚠ The model strips `{.underline}` as a heading ATTRIBUTE block, so its text is the shorter
    // one — pre-existing, and not what this row pins: the point is that the heading SURVIVES.
    expect(kept("### T [<section>]{.underline}")).toEqual(["h3:T [<section>]", "h2:Tail"]);
  });

  it("G8: a COMMENT, a CDATA section and a PROCESSING INSTRUCTION each consume their interior (`verify/v03`, `v14`, `v15`)", () => {
    expect(kept("### T <!-- <section> --> U")).toEqual(["h3:T <!-- <section> --> U", "h2:Tail"]);
    expect(kept("### T <![CDATA[<section>]]> U")).toEqual(["h3:T <![CDATA[<section>]]> U", "h2:Tail"]);
    // ⚠ A doubled `[` too, which quarto also renders — `<h3 …>T &lt;![CDATA[[]]&gt; U`
    // (`probes/cdata/cd1`). Both rows pass with the CDATA branch REMOVED, because the
    // bracketed-inline skip already covers them; see `headingAngleEnd` on why the branch is
    // kept anyway and what is not pinned.
    expect(kept("### T <![CDATA[[<section>]]> U")).toEqual(["h3:T <![CDATA[[<section>]]> U", "h2:Tail"]);
    expect(kept("### T <?xml <section> ?> U")).toEqual(["h3:T <?xml <section> ?> U", "h2:Tail"]);
  });

  it("G9: a quarto SHORTCODE is expanded before pandoc ever sees the tag (`verify/v17-shortcode`)", () => {
    expect(kept("### T {{< kbd <section> >}} U")).toEqual(["h3:T {{< kbd <section> >}} U", "h2:Tail"]);
  });

  it("G10: a raw INLINE TeX command swallows its own braced argument, tag and all (`verify/v04-texttt-braces`)", () => {
    expect(kept("### T \\texttt{<section>}")).toEqual(["h3:T \\texttt{<section>}", "h2:Tail"]);
  });

  it("G11: a tag inside ANOTHER tag's quoted attribute value is never a token of its own (`verify/v05-span-attr-div`)", () => {
    expect(kept('### T <span title="<div>">ok</span>')).toEqual([
      'h3:T <span title="<div>">ok</span>',
      "h2:Tail",
    ]);
  });

  it("G12: INLINE tag names keep the heading (`names1/` — the 14 either-tags and every non-block name)", () => {
    for (const tag of ["<span>", "<br/>", '<img src="x">', "<audio>", "<video>", "<del>", "</span>"]) {
      expect(kept(`### T ${tag}`)).toEqual([`h3:T ${tag}`, "h2:Tail"]);
    }
  });

  it("G13: an UNKNOWN name is not a block tag, and the match is never a prefix (`verify/v34`, `v35`, `refute k07`)", () => {
    for (const tag of ["<foo>", "</foo>", "<my-div>", "<x:section>", "<divider>", "<sections>", "<tablet>"]) {
      expect(kept(`### T ${tag}`)).toEqual([`h3:T ${tag}`, "h2:Tail"]);
    }
  });

  it("G14: angle brackets that are NOT a tag are ordinary text (`verify/v06`, `v32`, `v33`, `b_html_form/b20`-`b24`)", () => {
    for (const text of ["<section", "< section>", "<3", "<>", "<!section>", "< /section>", '<div title="a>']) {
      expect(kept(`### T ${text}`)).toEqual([`h3:T ${text}`, "h2:Tail"]);
    }
    expect(kept("### 5 < 6")).toEqual(["h3:5 < 6", "h2:Tail"]);
  });

  it("G15: class B (the five names AND every unknown macro) and class C never refuse a heading (`verify/v29`, `v30`, `c_tex/b1-five`, `b2-unknown`)", () => {
    for (const macro of ["\\clearpage", "\\newpage", "\\vspace{1cm}", "\\zzz{x}", "\\emph{x}", "\\LaTeX", "\\textbf{b}"]) {
      expect(kept(`### T ${macro}`)).toEqual([`h3:T ${macro}`, "h2:Tail"]);
    }
  });

  it("G16: an ARG-class macro whose arity is UNSATISFIED renders as literal text (`verify/v26`, `v28`, `c_tex/w1-arity`)", () => {
    for (const macro of ["\\section", "\\section*", "\\section[a]", "\\title[a]"]) {
      expect(kept(`### T ${macro}`)).toEqual([`h3:T ${macro}`, "h2:Tail"]);
    }
  });

  it("G17: a SETEXT title whose content holds only an INLINE tag is still a heading (`b_html_form/b62-setext-control`)", () => {
    expect(names(probe("T <span>u</span>", "===", "", "## Tail"))).toEqual([
      "h1:T <span>u</span>",
      "h2:Tail",
    ]);
  });

  it("G18: the heading BELOW a refused line is untouched, with or without a blank line (`d_context/a01`, `a12`)", () => {
    expect(names(probe("### T <section>", "## Next Heading", "", "## Tail")).slice(-2)).toEqual([
      "h2:Next Heading",
      "h2:Tail",
    ]);
    expect(names(probe("## T \\maketitle", "", "## Next Heading", "", "## Tail")).slice(-2)).toEqual([
      "h2:Next Heading",
      "h2:Tail",
    ]);
  });

  it("G19: a refused line leaves NO OPEN PARAGRAPH, so a setext title on the next line still forms (`state/s02`)", () => {
    expect(names(probe("### T <section>", "Some Title", "===", "", "## Tail")).slice(-2)).toEqual([
      "h1:Some Title",
      "h2:Tail",
    ]);
  });
});

describe("Session 269 — a block-level token anywhere in a heading's content means the line is no heading", () => {
  // R4 of `docs/REAL-DOCUMENT-RESCORE.md`. Pandoc parses an ATX header's content as INLINES; where
  // the inline parser refuses a token — a block-level raw HTML tag, or a raw-LaTeX block command —
  // `many inline` stops short, the header's closing parser fails, and the whole `atxHeader` parse
  // fails, so the line is emitted as raw text with no heading at all. The same holds for a setext
  // title. Every expectation is a `quarto render --to html --no-execute` (quarto 1.7.33 /
  // pandoc 3.6.3) of these exact bytes, `scratchpad/s269/probes/`, re-run firsthand.
  const names = (lines: string[]) =>
    findHeadings(lines.join("\n") + "\n").map((h) => `h${h.level}:${h.text}`);
  const probe = (...body: string[]) => ["---", "title: probe", "engine: markdown", "---", "", ...body];

  it("R4a: `## \\maketitle` is no heading — the corpus shape, ordinal 1985 (`probes/real/real-shapes`)", () => {
    expect(names(probe("## Kept Before", "", "## \\maketitle", "", "## Kept After"))).toEqual([
      "h2:Kept Before",
      "h2:Kept After",
    ]);
  });

  it("R4b: `### 1. <Section heading>` is no heading — the corpus shape, ordinal 3004 (`probes/real/real-shapes`)", () => {
    // Capitalised, and carrying what looks like an attribute: the tag name is canonicalised to
    // `section` before the block-set test, and `heading` is attribute soup.
    expect(
      names(probe("## Kept Before", "", "### 1. <Section heading>", "", "## Kept After")),
    ).toEqual(["h2:Kept Before", "h2:Kept After"]);
  });

  // ── R4c-R4l are LABELLED TEST-AFTER. R4a and R4b are the session's two REDs and are what
  // drove the code; the rows below pin the rest of the surface those two commits already cover,
  // written afterwards and run once to confirm no gap. Every one is still a `quarto render`
  // of those exact bytes, not an inference from the implementation.

  it("R4c: a SETEXT title is refused by the same rule, under both underlines (`b_html_form/b60`, `b61`, `c_tex/s1`)", () => {
    expect(names(probe("T <section>", "===", "", "## Tail"))).toEqual(["h2:Tail"]);
    expect(names(probe("T <div>", "---", "", "## Tail"))).toEqual(["h2:Tail"]);
    expect(names(probe("T \\maketitle", "===", "", "## Tail"))).toEqual(["h2:Tail"]);
  });

  it("R4d: a CLOSING block tag refuses too — except `</script>`, alone in the list (`names2/`)", () => {
    expect(names(probe("### T </section>", "", "## Tail"))).toEqual(["h2:Tail"]);
    expect(names(probe("### T </div class=\"a\">", "", "## Tail"))).toEqual(["h2:Tail"]);
    expect(names(probe("### T </script>", "", "## Tail"))).toEqual(["h3:T </script>", "h2:Tail"]);
  });

  it("R4e: NONE of the sixteen either-tags refuses — `applet` and `object` included (`names1/`)", () => {
    // ⚠ The extractor this project scores with reports NO heading for `<applet>` and `<object>`,
    // because their element swallows the rest of the HTML including the heading's own `</h3>`.
    // The render contains `<h3 class="anchored">T098 <applet>`, so the heading is real and this
    // row is a DELETION guard, not a phantom one.
    for (const tag of ["<applet>", "<object>", "<svg>", "<iframe>", "<audio>", "<video>", "<ins>"]) {
      expect(names(probe(`### T ${tag}`, "", "## Tail"))).toEqual([`h3:T ${tag}`, "h2:Tail"]);
    }
  });

  it("R4f: `<textarea>` and `<title>` refuse as openers, and `<script>`/`<style>` do (`names1/`, `verify/v01`, `v02`)", () => {
    for (const tag of ["<textarea>", "<title>", "<script>", "<style>"]) {
      expect(names(probe(`### T ${tag}`, "", "## Tail"))).toEqual(["h2:Tail"]);
    }
  });

  it("R4g: the ARG arity needs a BRACED group and the BARE arity ignores one (`verify/v25`, `v27`, `c_tex/a4-bare`)", () => {
    expect(names(probe("### T \\section{x}", "", "## Tail"))).toEqual(["h2:Tail"]);
    expect(names(probe("### T \\section[a]{x}", "", "## Tail"))).toEqual(["h2:Tail"]);
    expect(names(probe("### T \\section {x}", "", "## Tail"))).toEqual(["h2:Tail"]);
    expect(names(probe("### T \\par{x}", "", "## Tail"))).toEqual(["h2:Tail"]);
    expect(names(probe("### T \\item{x}", "", "## Tail"))).toEqual(["h2:Tail"]);
  });

  it("R4h: there is NO TAIL RULE, and the position in the content does not matter (`c_tex/p1-position`, `p2-tail`)", () => {
    expect(names(probe("### T \\maketitle and more words", "", "## Tail"))).toEqual(["h2:Tail"]);
    expect(names(probe("### \\maketitle at the start", "", "## Tail"))).toEqual(["h2:Tail"]);
    expect(names(probe("### <section> at the start", "", "## Tail"))).toEqual(["h2:Tail"]);
    expect(names(probe("### T <section> in the middle", "", "## Tail"))).toEqual(["h2:Tail"]);
  });

  it("R4i: every level is refused alike (`d_context/f01`-`f06`, `g01`-`g06`)", () => {
    for (let level = 1; level <= 6; level++) {
      expect(names(probe(`${"#".repeat(level)} T <section>`, "", "## Tail"))).toEqual(["h2:Tail"]);
      expect(names(probe(`${"#".repeat(level)} T \\maketitle`, "", "## Tail"))).toEqual(["h2:Tail"]);
    }
  });

  it("R4j: a trailing ATTRIBUTE BLOCK and a closing HASH RUN do not rescue the line (`b_html_form/b65`, `b66`)", () => {
    expect(names(probe("### T <section> {#myid}", "", "## Tail"))).toEqual(["h2:Tail"]);
    expect(names(probe("### T <section> ###", "", "## Tail"))).toEqual(["h2:Tail"]);
    expect(names(probe("## T \\maketitle ##", "", "## Tail"))).toEqual(["h2:Tail"]);
  });

  it("R4k: the tag NAME ends at the first whitespace, `/` or `>` (`verify/v07`, `v08`, `d_context_refute/r29`-`r31`)", () => {
    expect(names(probe("### T <section/foo>", "", "## Tail"))).toEqual(["h2:Tail"]);
    expect(names(probe("### T <div title=a>b>", "", "## Tail"))).toEqual(["h2:Tail"]);
    expect(names(probe('### T <div"a">', "", "## Tail"))).toEqual(['h3:T <div"a">', "h2:Tail"]);
    expect(names(probe("### T <section=x>", "", "## Tail"))).toEqual(["h3:T <section=x>", "h2:Tail"]);
  });

  it("R4l: the two halves have DIFFERENT reader sets, measured on the same nine documents (`probes/readers/`)", () => {
    const reader = (from: string, body: string) =>
      findHeadings(["---", "title: probe", "engine: markdown", `from: ${from}`, "---", "", body, "", "## Tail"].join("\n") + "\n")
        .map((h) => `h${h.level}:${h.text}`);
    // markdown refuses BOTH halves.
    expect(reader("markdown", "### T <section>")).toEqual(["h2:Tail"]);
    expect(reader("markdown", "## T \\maketitle")).toEqual(["h2:Tail"]);
    // markdown_mmd / markdown_phpextra refuse the TAG and keep the MACRO — they carry no raw_tex.
    for (const from of ["markdown_mmd", "markdown_phpextra"]) {
      expect(reader(from, "### T <section>")).toEqual(["h2:Tail"]);
      expect(reader(from, "## T \\maketitle")).toEqual(["h2:T \\maketitle", "h2:Tail"]);
    }
    // The five that refuse NEITHER.
    for (const from of ["gfm", "commonmark", "commonmark_x", "markdown_strict", "markdown_github"]) {
      expect(reader(from, "### T <section>")).toEqual(["h3:T <section>", "h2:Tail"]);
      expect(reader(from, "## T \\maketitle")).toEqual(["h2:T \\maketitle", "h2:Tail"]);
    }
    // An EXTENSION outranks the base, independently per half (`verify/v40-minus-raw_html`, `v40-minus-raw_tex`).
    expect(reader("markdown-raw_html", "### T <section>")).toEqual(["h3:T <section>", "h2:Tail"]);
    expect(reader("markdown-raw_html", "## T \\maketitle")).toEqual(["h2:Tail"]);
    expect(reader("markdown-raw_tex", "## T \\maketitle")).toEqual(["h2:T \\maketitle", "h2:Tail"]);
    expect(reader("markdown-raw_tex", "### T <section>")).toEqual(["h2:Tail"]);
    // An unreadable value is not a measured base, so the fail-safe answer KEEPS the heading.
    expect(reader("not a reader name", "### T <section>")).toEqual(["h3:T <section>", "h2:Tail"]);
  });

  it("R4m: an UNTERMINATED comment masks nothing, and `<!DOCTYPE` is not a masker at all (`verify/v09`, `v12`, `v13`)", () => {
    expect(names(probe("### T <!-- <section>", "", "## Tail"))).toEqual(["h2:Tail"]);
    expect(names(probe("### T <!-- c --> <section>", "", "## Tail"))).toEqual(["h2:Tail"]);
    expect(names(probe("### T <!DOCTYPE <section>> U", "", "## Tail"))).toEqual(["h2:Tail"]);
  });
});

describe("R5 — knitr's chunk grammar is wider than quarto's cell grammar (Session 273)", () => {
  // In a KNITR document quarto runs `knitr::knit()` BEFORE pandoc, and knitr's chunk pattern
  // (knitr 1.51, `all_patterns[["md"]]$chunk.begin`) accepts `[a-zA-Z0-9_]+` as the engine name
  // where quarto's cell recognizer `CELL_INFO` accepts `[=A-Za-z]+`. knitr rewrites every chunk
  // it claims to `::: {.cell}` + ```{.LANG .cell-code} -- observed in the `keep-md` intermediate,
  // not inferred -- so pandoc pairs the fence and the heading below it survives.
  //
  // MEASURED, `quarto render` with real knitr execution (quarto 1.7.33, knitr 1.51, R 4.6.1),
  // these exact bytes saved as `.Rmd`: exit 0, one <h4>. This model reports none.
  const r5 = (tag: string, fence = "```"): string =>
    [
      "---",
      "title: r5",
      "---",
      "",
      "```{r}",
      "x <- 1",
      "```",
      "",
      fence + "{" + tag + "}",
      "int a;",
      "",
      "int b;",
      fence,
      "",
      "#### After Chunk",
      "",
      "prose",
      "",
      fence,
      "plain",
      fence,
      "",
    ].join("\n");

  it("a knitr document's digit-bearing engine chunk opens a region, so the heading below survives", () => {
    expect(findHeadings(r5("zzz9, eval = FALSE"), "knitr").map((h) => h.text)).toEqual([
      "After Chunk",
    ]);
  });

  // ⚠ NOT an anti-phantom pin. It is HEAD's behaviour, UNCHANGED by Session 273 -- and it is a
  // MEASURED quarto/Posit DISAGREEMENT, now DECIDED: `BACKLOG.md` RECORD decision (6),
  // Session 274. We follow `quarto render`. This row is the pin for that decision.
  //
  // `quarto render` on these bytes as a `.qmd` with `engine: markdown` emits NO <h4> (exit 0,
  // measured), and this model reports none -- so we follow the RENDER oracle. But Posit's
  // Outline SHOWS the heading: observed, not inferred, by `npm run observe:posit` (Session 273,
  // probe `r02_r5_qmd_markdown`, quarto.quarto 1.135.0, `ours-loaded: false`, both controls
  // green) -- Posit pairs the fence engine-blind and reports `(code cell)` for it.
  //
  // ⚠ WHY THIS ONE DOES NOT MIRROR POSIT, WHEN DECISIONS (2)-(5) ALL DID. Posit's own
  // maintainers have disowned the behaviour upstream. `quarto-dev/quarto#829` (OPEN, filed
  // 2025-09-26 by vezwork, the Quarto VS Code extension maintainer): "it does seem that the
  // outline should match the TOC that ends up in the rendered document" -- and cscheid, on
  // quarto-cli, answers that quarto-cli should own outline generation for clients. So the
  // engine-blind pairing is an acknowledged open DEFECT on their side, not a design choice, and
  // mirroring it would copy a bug its own authors intend to remove. Read firsthand at Session
  // 274 Phase 0, `gh issue view 829 --repo quarto-dev/quarto`.
  //
  // ⚠ And it is PRE-EXISTING: Session 273 moved the knitr arm only, where quarto and Posit
  // AGREE with each other and with the fix. Mirroring Posit would also be a WIDENING in the
  // phantom-vs-render direction whose corpus reach was never measured.
  it("the SAME bytes under the markdown engine, or with no engine known, are UNCHANGED from HEAD", () => {
    expect(findHeadings(r5("zzz9, eval = FALSE"), "markdown")).toEqual([]);
    expect(findHeadings(r5("zzz9, eval = FALSE"))).toEqual([]);
  });

  // ⚠ THE LEADING-LETTER NARROWING, AND WHY IT IS NOT knitr's OWN GRAMMAR. knitr claims a
  // digit-led or `_`-led engine name, but its rewrite target is a pandoc CLASS and pandoc
  // refuses one that does not start with a letter -- so the runaway happens anyway, one stage
  // later, and HEAD is already RIGHT. Widening `KNITR_CHUNK_INFO` to knitr's `[a-zA-Z0-9_]+`
  // turns each of these into a PHANTOM against `quarto render`. Measured on `.Rmd` with real
  // knitr execution, exit 0 each: <h4> count 0 for both rows below and 1 for every row above.
  // ⚠ Posit SHOWS the heading here (observed, probe `r03_digit_led_rmd`) -- the same
  // quarto/Posit question as the markdown-engine row above, DECIDED with it as RECORD decision
  // (6) (Session 274): we follow `quarto render`. The reasoning is on that row, not repeated here.
  it("a digit-led or underscore-led engine name stays lost -- pandoc refuses the rewritten class", () => {
    expect(findHeadings(r5("2x, eval = FALSE"), "knitr")).toEqual([]);
    expect(findHeadings(r5("_zzz, eval = FALSE"), "knitr")).toEqual([]);
  });

  // knitr's class is `[a-zA-Z0-9_]+`, so an UNDERSCORE with no digit is claimed too -- the
  // shape corpus ordinal 2383 holds. Measured: `quarto render` on `.Rmd` gives one <h4>.
  it("an underscore-bearing engine name is claimed by knitr just as a digit-bearing one is", () => {
    expect(findHeadings(r5("glue_sql, eval = FALSE"), "knitr").map((h) => h.text)).toEqual([
      "After Chunk",
    ]);
  });

  // A HYPHEN or a DOT is outside knitr's class, so knitr leaves the chunk for pandoc, which
  // refuses it -- and quarto loses the heading too. Measured, `.Rmd`, exit 0: <h4> count 0.
  // These are NOT part of R5. ⚠ Posit shows the heading here too (probe `r05_hyphen_rmd`);
  // same question as above, and DECIDED with it as RECORD decision (6) (Session 274).
  it("a hyphen or a dot in the engine name is not knitr's either, and quarto loses the heading too", () => {
    expect(findHeadings(r5("r-foo, eval = FALSE"), "knitr")).toEqual([]);
    expect(findHeadings(r5("r.foo, eval = FALSE"), "knitr")).toEqual([]);
  });

  // ⚠ BACKTICK ONLY, and this gate still must not fire here: knitr's `chunk.begin` is anchored
  // at a backtick run and `keep-md` leaves a `~~~` chunk verbatim, so knitr is not the cause and
  // widening the gate to tilde would break Session 263's tilde rows. Session 273 filed the
  // resulting deletion as a defect and predicted its cause was "in the pandoc layer".
  //
  // ⚠ **THAT PREDICTION HELD, AND SESSION 277 CLOSED IT WITHOUT TOUCHING THIS GATE.** The
  // heading was lost because the chunk's own `~~~` closer, sitting under the open paragraph
  // `int b;`, was read as an OPENER and ran to the fence below the prose. A tilde opener does not
  // interrupt an open paragraph in pandoc (`paragraphInterruptRefuses`), so it no longer opens
  // one here. Re-measured firsthand on THESE bytes as `.Rmd` with real knitr execution
  // (`scratchpad/s277/r5tilde/t01_tilde.Rmd`, exit 0): `quarto render` emits the <h4>, HEAD
  // reported NOTHING, and this build reports it -- both oracles now agree with the model, since
  // Posit's Outline also lists it (observed, Session 273, probe `r06_tilde_rmd`).
  it("a TILDE fence of the same shape now KEEPS the heading -- Session 277 fixed the pandoc-layer cause", () => {
    expect(findHeadings(r5("zzz9, eval = FALSE", "~~~"), "knitr").map((h) => h.text)).toEqual([
      "After Chunk",
    ]); // quarto: h4:After Chunk -- measured, .Rmd, real knitr, exit 0
    // CONTROL -- the backtick twin, which knitr DOES claim, is unmoved (same probe dir, `t02`).
    expect(findHeadings(r5("zzz9, eval = FALSE"), "knitr").map((h) => h.text)).toEqual([
      "After Chunk",
    ]);
  });

  // The gate decides PAIRING ONLY. It must never manufacture a cell -- that is `CELL_INFO`'s
  // job and its docstring forbids widening it. If this row ever returns `["r", "zzz9"]` the
  // change has leaked into cell-option validation, run-cell and the squiggle surface.
  it("the claimed chunk is NOT a cell -- no new cell.lang, no new validation surface", () => {
    expect(findAllCells(r5("zzz9, eval = FALSE")).map((c) => c.lang)).toEqual(["r"]);
  });

  // The two STRUCTURAL preconditions, each measured to be load-bearing: without the blank line
  // in the chunk body `consumedCloserLine` swallows the closer into an inline code span, and
  // without a bare fence below `hasCloserBelow` declines -- so HEAD keeps the heading either
  // way and the defect needs both. They pin that the fix did not make the gate do their work.
  it("neither structural precondition is needed once knitr claims the chunk", () => {
    const noBlank = r5("zzz9, eval = FALSE").replace("int a;\n\nint b;", "int a;\nint b;");
    expect(findHeadings(noBlank, "knitr").map((h) => h.text)).toEqual(["After Chunk"]);
    expect(findHeadings(noBlank).map((h) => h.text)).toEqual(["After Chunk"]);
  });
});

describe("R6 — knitr consumes a chunk's closer before pandoc sees it, so a stray fence above the chunk stays unclosed (Session 275)", () => {
  // In a KNITR document quarto runs `knitr::knit()` BEFORE pandoc, and knitr replaces every chunk
  // it claims with that chunk's OUTPUT. A stray bare ``` that belongs to no chunk is left verbatim,
  // but the chunk's own closing ``` never reaches pandoc -- so pandoc finds nothing to close the
  // stray fence, reads it as literal paragraph text (`<p>```</p>`), and renders the heading below.
  // This model paired the stray fence with the chunk's closer and deleted the heading.
  //
  // MEASURED, these exact bytes saved as `.Rmd` (quarto 1.7.33, knitr 1.51): `quarto render --to
  // html` exit 0 with real execution AND with `--no-execute` -- both <h2> present, the stray fence
  // rendered as `<p>```</p>`. The `keep-md` intermediate shows the chunk replaced by `::: {.cell}`
  // / `::: {.cell-output-display}` / an image with real execution (an empty `::: {.cell}` / `:::`
  // with `--no-execute`), and no backtick line anywhere below the stray fence in either.
  const r6 = (options: string, body = "plot(pressure)"): string =>
    [
      "prose",
      "",
      "```",
      "",
      "## Heading Under Test",
      "",
      "```{r demo, " + options + "}",
      body,
      "```",
      "",
      "## Heading After Chunk",
      "",
      "tail prose",
      "",
    ].join("\n");

  it("a stray bare fence above an echo=FALSE chunk does not pair with that chunk's closer", () => {
    expect(findHeadings(r6("echo=FALSE"), "knitr").map((h) => h.text)).toEqual([
      "Heading Under Test",
      "Heading After Chunk",
    ]);
  });

  // Once an ECHOED chunk further down gives the stray fence a real closer, the fence opens --
  // and it must not close early on the silent chunk's closer, which pandoc never sees. knitr
  // re-emits the echoed chunk as ```{.r .cell-code} + a bare closer, and that bare closer is what
  // pairs with the stray fence. MEASURED, these bytes as `.Rmd`, exit 0 with real execution and
  // with `--no-execute`: ONLY "Heading After Chunk" renders, the first two inside the <pre>.
  it("a stray fence that does open skips the silent chunk's closer and pairs with the echoed chunk's", () => {
    const text = [
      "prose",
      "",
      "```",
      "",
      "## Heading Under Test",
      "",
      "```{r quiet, echo=FALSE}",
      "x <- 1",
      "```",
      "",
      "## Heading Between Chunks",
      "",
      "```{r shown, echo=TRUE}",
      "y <- 2",
      "```",
      "",
      "## Heading After Chunk",
      "",
      "tail prose",
      "",
    ].join("\n");
    expect(findHeadings(text, "knitr").map((h) => h.text)).toEqual(["Heading After Chunk"]);
  });

  // A LEADING `#| ` option line silences a chunk as the header does. MEASURED, `.Rmd`, exit 0 in
  // both modes: both <h2> render for `echo: false`, `echo: no` and `echo: false # hide`.
  it("a leading `#| echo: false` line silences the chunk", () => {
    const both = ["Heading Under Test", "Heading After Chunk"];
    expect(findHeadings(r6("fig.width=4", "#| echo: false\nplot(pressure)"), "knitr").map((h) => h.text)).toEqual(both);
  });

  // ⚠ A `#|` value OVERRIDES the header, and reading the header first is a DELETION waiting for a
  // later closer. MEASURED, `.Rmd`, exit 0 in both modes: header `echo=FALSE` + `#| echo: true`
  // is ECHOED -- the stray fence opens a <pre> and only "Heading After Chunk" renders.
  it("a leading `#| echo: true` overrides the header's echo=FALSE, so the chunk still echoes", () => {
    expect(findHeadings(r6("echo=FALSE", "#| echo: true\nplot(pressure)"), "knitr").map((h) => h.text)).toEqual([
      "Heading After Chunk",
    ]);
  });

  // An `echo=FALSE` INSIDE a quoted option value is text, not an option. MEASURED, `.Rmd`, exit 0
  // in both modes, double and single quotes alike: ECHOED, only "Heading After Chunk" renders.
  it("an echo=FALSE or include=FALSE inside a quoted option value does not silence the chunk", () => {
    const after = ["Heading After Chunk"];
    expect(findHeadings(r6('fig.cap="a, echo=FALSE, b"'), "knitr").map((h) => h.text)).toEqual(after);
    expect(findHeadings(r6("fig.cap='x, include=FALSE, y'"), "knitr").map((h) => h.text)).toEqual(after);
  });
});

describe("R6 — a chunk is silent only when that is POSITIVELY established (Session 275, adversarial pass)", () => {
  // ⚠ A chunk read as silent when it is not DELETES headings: the stray fence skips that chunk's
  // closer and pairs with the next one below. This shape makes the misread visible -- a later
  // plain block gives the stray fence a closer further down, so a wrong "silent" swallows
  // "Heading After Chunk" too. MEASURED, every row here as `.Rmd` (quarto 1.7.33, knitr 1.51),
  // `quarto render --to html` exit 0 with real execution AND `--no-execute`, the two agreeing: a
  // truly silent chunk renders only "Heading Tail"; a chunk that emits a fence renders
  // "Heading After Chunk" and "Heading Tail". Each row below was found by the adversarial pass
  // against the first cut of this rule (commit b1f054ac), which deleted "Heading After Chunk".
  const r6x = (header: string, body = "plot(pressure)"): string =>
    [
      "prose",
      "",
      "```",
      "",
      "## Heading Under Test",
      "",
      "```{" + header + "}",
      body,
      "```",
      "",
      "## Heading After Chunk",
      "",
      "```text",
      "plain block",
      "```",
      "",
      "## Heading Tail",
      "",
      "tail prose",
      "",
    ].join("\n");
  const knitr = (text: string) => findHeadings(text, "knitr").map((h) => h.text);
  const emits = ["Heading After Chunk", "Heading Tail"];

  // quarto re-emits a `dot`/`mermaid` chunk as its own fenced block whatever `echo` says, and an
  // `engine=` option moves an `{r}` chunk onto such an engine. Only knitr's R engine is trusted.
  it("echo=FALSE does not silence an engine that re-emits its own fence", () => {
    expect(knitr(r6x("dot, echo=FALSE", "digraph { a -> b }"))).toEqual(emits);
    expect(knitr(r6x("mermaid, echo=FALSE", "graph TD; A-->B"))).toEqual(emits);
    expect(knitr(r6x('r demo, engine="dot", echo=FALSE', "digraph { a -> b }"))).toEqual(emits);
  });

  // knitr parses the header as R arguments, so an `echo=FALSE` INSIDE a call is an argument to
  // that call and sets no chunk option. A header this cannot read flat is not read at all.
  // ⚠ The `paste(...)` row is the one that needs the bracket test: split on commas, every piece of
  // it LOOKS like an assignment, so a comma-only reading takes `echo=FALSE` as the chunk's own
  // (a mutant without the bracket test survived every other row). An R raw string is refused
  // too. Both measured, exit 0 in both modes, ECHOED.
  it("an echo=FALSE nested inside an R call in the header does not silence the chunk", () => {
    expect(knitr(r6x('r demo, fig.cap=c("a", echo=FALSE, "b")'))).toEqual(emits);
    expect(knitr(r6x('r demo, out.extra=paste("a", echo=FALSE, sep="")'))).toEqual(emits);
    expect(knitr(r6x('r demo, fig.cap=r"(a", echo=FALSE, "b)"'))).toEqual(emits);
  });

  // knitr reads a `#|` block as YAML only in its plain shape, and otherwise as something else
  // entirely -- so each of these ECHOES: no space after the colon (knitr takes the line as a
  // label), two spaces after `#|`, R syntax overriding the header's echo=FALSE, an `echo: false`
  // nested in a block scalar, and `false#hide`, which YAML reads as one string.
  it("a `#|` line that is not in the plain `#| key: value` shape does not silence the chunk", () => {
    expect(knitr(r6x("r demo", "#| echo:false\nplot(pressure)"))).toEqual(emits);
    expect(knitr(r6x("r demo", "#|  echo: false\nplot(pressure)"))).toEqual(emits);
    expect(knitr(r6x("r demo, echo=FALSE", "#| echo=TRUE\nplot(pressure)"))).toEqual(emits);
    expect(knitr(r6x("r demo", "#| fig-cap: |\n#|   echo: false\nplot(pressure)"))).toEqual(emits);
    expect(knitr(r6x("r demo", "#| echo: false#hide\nplot(pressure)"))).toEqual(emits);
  });

  // knitr's `\s` is ASCII; JavaScript's also matches U+00A0. A header line ending in a
  // NO-BREAK SPACE is no chunk to knitr, so its closer reaches pandoc like any other.
  it("a chunk header ending in a no-break space is not claimed by knitr, so its closer is kept", () => {
    const text = r6x("r demo, echo=FALSE").replace("```{r demo, echo=FALSE}", "```{r demo, echo=FALSE}\u00a0");
    expect(knitr(text)).toEqual(emits);
  });

  // ⚠ Withholding a closer lets a fence run FURTHER, so it must reach only the fence R6 is about:
  // a top-level, unquoted opener that pandoc also opens. Both of these are fences to this model
  // and NOT to pandoc -- a bare fence inside a list item closes nothing outside its item, and a
  // backtick in a backtick fence's info string is no fence at all -- so quarto renders A, B and
  // C (measured, exit 0 in both modes, `<p>```</p>` in the raw HTML). HEAD already loses A, a
  // PRE-EXISTING defect this rule does not touch; what it must not do is carry that runaway past
  // the silent chunk into B, which the first cut of this rule did.
  it("a fence pandoc does not open is not carried past a silent chunk's closer", () => {
    const tail = ["", "## A", "", "```{r quiet, echo=FALSE}", "x <- 1", "```", "", "## B", "", "```text", "plain block", "```", "", "## C", "", "tail", ""];
    const listItem = ["prose", "", "- item", "  ```", ...tail].join("\n");
    const backtickInfo = ["prose", "", "```a`b", ...tail].join("\n");
    expect(knitr(listItem)).toEqual(["B", "C"]);
    expect(knitr(backtickInfo)).toEqual(["B", "C"]);
  });

  // GUARDS, added after GREEN and passing on arrival, in the same deletion-visible shape and each
  // measured the same way. The first row is silent through the SECOND line of a `#|` run -- the
  // usual Quarto style, which a reader of only the first line misses. The rest are the header
  // spellings knitr reads as a flat option list.
  it("GUARD: the silencing spellings a positive reading must keep", () => {
    const silent = ["Heading Tail"];
    expect(knitr(r6x("r demo", "#| fig-height: 4\n#| echo: false\nplot(pressure)"))).toEqual(silent);
    expect(knitr(r6x("r demo", "#| echo: no\nplot(pressure)"))).toEqual(silent);
    expect(knitr(r6x("r demo, echo=TRUE", "#| include: false\nplot(pressure)"))).toEqual(silent);
    expect(knitr(r6x("r echo=FALSE"))).toEqual(silent);
    expect(knitr(r6x("r demo, echo = FALSE"))).toEqual(silent);
    expect(knitr(r6x("r demo, include=F"))).toEqual(silent);
    expect(knitr(r6x("r demo, echo=TRUE, echo=FALSE"))).toEqual(silent);
  });

  // ⚠ Each of these ECHOES, and reading it as silent deletes "Heading After Chunk": a value that
  // is not literally FALSE or F (`!FALSE`, `1`), and a name that only ENDS in `echo`.
  it("GUARD: a header value or name that is not exactly echo=FALSE does not silence", () => {
    expect(knitr(r6x("r demo, echo=!FALSE"))).toEqual(emits);
    expect(knitr(r6x("r demo, echo=1"))).toEqual(emits);
    expect(knitr(r6x("r demo, code_echo=FALSE"))).toEqual(emits);
  });

  // ⚠ IRREGULAR knitr pairing keeps HEAD's answer for the WHOLE document -- a deliberate
  // fallback, NOT a match with quarto, and these rows pin it as such. Each document discriminates:
  // without the bail the answer changes. A later chunk UNCLOSED at end of file: quarto deletes
  // its opener before knitr runs and renders H1 and H2 (measured, exit 0 in both modes), where
  // HEAD, and so this, loses H1. A later chunk whose closer is LONGER than its opener: knitr
  // treats it as unclosed and quarto renders only H3 (measured, exit 0 in both modes), where HEAD
  // keeps a phantom H2. Both are PRE-EXISTING residuals; following knitr exactly here needs
  // quarto's own opener repair, which a stray fence above can switch off (measured).
  it("GUARD: an unclosed or mismatched later chunk keeps HEAD's pairing for the whole document", () => {
    const head = ["prose", "", "```", "", "## H1", "", "```{r a, echo=FALSE}", "plot(pressure)", "```", "", "## H2", "", "```{r b}", "x <- 1"];
    const unclosed = [...head, ""].join("\n");
    const mismatched = [...head, "````", "", "## H3", "", "tail", ""].join("\n");
    const blind = (text: string) => findHeadings(text).map((h) => h.text);
    expect(knitr(unclosed)).toEqual(blind(unclosed));
    expect(knitr(unclosed)).toEqual(["H2"]);
    expect(knitr(mismatched)).toEqual(blind(mismatched));
    expect(knitr(mismatched)).toEqual(["H2", "H3"]);
  });
});

describe("R6 GUARD — what a knitr chunk's options may and may not silence (Session 275)", () => {
  // GUARDS, added after GREEN and passing on arrival -- each pins a shape the R6 rule bounds.
  // Unless a row says otherwise, its expectation is a MEASURED `quarto render` of these exact
  // bytes as `.Rmd` (quarto 1.7.33, knitr 1.51), exit 0 with real execution AND with
  // `--no-execute`, the two agreeing: a `plot()` body prints no text, so no output fence can
  // re-close the stray fence. The rows that are NOT a quarto match say so where they stand.
  const r6 = (options: string, body = "plot(pressure)"): string =>
    [
      "prose",
      "",
      "```",
      "",
      "## Heading Under Test",
      "",
      "```{r demo, " + options + "}",
      body,
      "```",
      "",
      "## Heading After Chunk",
      "",
      "tail prose",
      "",
    ].join("\n");
  const both = ["Heading Under Test", "Heading After Chunk"];
  const after = ["Heading After Chunk"];
  const knitr = (text: string) => findHeadings(text, "knitr").map((h) => h.text);

  it("the silencing spellings: include, F, a YAML `no`, a trailing YAML comment, the LAST duplicate", () => {
    expect(knitr(r6("include=FALSE"))).toEqual(both);
    expect(knitr(r6("echo=F"))).toEqual(both);
    expect(knitr(r6("fig.width=4", "#| echo: no\nplot(pressure)"))).toEqual(both);
    expect(knitr(r6("fig.width=4", "#| echo: false # hide\nplot(pressure)"))).toEqual(both);
    expect(knitr(r6("echo=TRUE", "#| include: false\nplot(pressure)"))).toEqual(both);
    expect(knitr(r6("echo=TRUE, echo=FALSE"))).toEqual(both);
  });

  // ⚠ Each of these ECHOES, so reading it as silent would DELETE a heading the moment a closer
  // sits further down. `#|echo:` needs the space to be an option at all; a `#|` line is an option
  // only in the LEADING run; a quoted YAML `'false'` is a string; the last duplicate wins.
  it("the spellings that do NOT silence -- the chunk still echoes and re-closes the stray fence", () => {
    expect(knitr(r6("fig.width=4", "#|echo: false\nplot(pressure)"))).toEqual(after);
    expect(knitr(r6("fig.width=4", "plot(pressure)\n#| echo: false"))).toEqual(after);
    expect(knitr(r6("fig.width=4", "#| echo: 'false'\nplot(pressure)"))).toEqual(after);
    expect(knitr(r6("echo=FALSE, echo=TRUE"))).toEqual(after);
  });

  it("an echoed chunk is unchanged from HEAD: echo=TRUE, no options, and eval=FALSE (which still echoes)", () => {
    expect(knitr(r6("echo=TRUE"))).toEqual(after);
    expect(knitr(r6("fig.width=4"))).toEqual(after);
    expect(knitr(r6("eval=FALSE"))).toEqual(after);
  });

  // The silent chunk's OWN opener still pairs with its closer, so its body stays code -- a
  // blank-separated `# a comment` inside it is not a heading. Measured: exit 0, both <h2>, no <h1>.
  it("a silent chunk's body stays code", () => {
    const text = r6("echo=FALSE", "x <- 1\n\n# a comment in the chunk\n\ny <- 2");
    expect(knitr(text)).toEqual(both);
  });

  // ⚠ A NESTED opener makes the whole document keep HEAD's pairing (a deliberate fallback). Here
  // it also matches quarto: measured exit 0, only "Heading After Chunk" in both modes. The
  // unclosed and mismatched-closer fallbacks are pinned with documents that discriminate, in the
  // "POSITIVELY established" block above.
  it("a nested opener keeps HEAD's pairing for the whole document", () => {
    const nested = r6("echo=FALSE", "x <- 1\n```{r second}\ny <- 2");
    expect(knitr(nested)).toEqual(after);
  });

  // The rule is knitr's, so it must not leak. These bytes behind an `engine: markdown` front
  // matter, as `.qmd`, render exit 0 with only "Heading After Chunk" and a <pre> -- measured. (The
  // bare bytes cannot be rendered under the markdown engine: quarto sends them to knitr.)
  it("the markdown engine, and no engine known, are unchanged from HEAD", () => {
    expect(findHeadings(r6("echo=FALSE"), "markdown").map((h) => h.text)).toEqual(after);
    expect(findHeadings(r6("echo=FALSE")).map((h) => h.text)).toEqual(after);
  });

  // The Outline now reaches the chunk the stray fence used to swallow, as a cell under the
  // recovered heading -- quarto runs that chunk. ⚠ Only the engine-aware Outline sees it: Run
  // Cell and diagnostics call the model with no engine and still pair the stray fence (recorded
  // in `BACKLOG.md`, Session 275).
  it("the Outline lists the silent chunk as a cell under the recovered heading", () => {
    const outline = buildOutline(r6("echo=FALSE"), "knitr");
    expect(outline.map((s) => s.name)).toEqual(both);
    expect(outline[0].children.map((c) => c.kind)).toEqual(["cell"]);
  });
});

describe("a fence interrupts an open PARAGRAPH only as a COLUMN-0 BACKTICK run (Session 277)", () => {
  const doc = (...lines: string[]) => lines.join("\n") + "\n";
  const names = (text: string) => findHeadings(text).map((h) => `h${h.level}:${h.text}`);

  it("RED->GREEN: a backtick opener INDENTED 1-3 below a paragraph line is not a fence, so the heading below it survives", () => {
    // ⚠ THE DEFECT, and it is a heading DELETION -- the cardinal sin. Rendered firsthand through
    // the real `quarto render` 1.7.33 on these exact bytes (`scratchpad/s277/probes/pi01`-`pi03`,
    // `posit/s01_para_bt_indent1`): quarto emits BOTH headings, and HEAD reports only the second.
    //
    // Pandoc's markdown reader gives a fence NO paragraph-interrupt power at indent 1-3: the line
    // is ordinary paragraph text, so the blank line below it really does end the paragraph and
    // `## Alpha Indent One` is a heading. `fenceColumns` is already `[0]` here, but `fenceMatchAt`
    // turns a column LIST into a TOLERANCE (`columnIsCodeDepth`, base 0 => columns 0-3 pass), so
    // the opener was accepted and its region swallowed the heading.
    expect(
      names(doc("prose line", " ```", "", "## Alpha Indent One", "", "```text", "plain block",
                "```", "", "## Bravo Tail", "", "tail")),
    ).toEqual(["h2:Alpha Indent One", "h2:Bravo Tail"]); // quarto: both — measured, exit 0
  });

  it("RED->GREEN: a TILDE opener at column 0 below a paragraph line is not a fence either", () => {
    // ⚠ THE SECOND HALF, and it is the half no corpus document can justify: the frozen 3,383-
    // document corpus contains NO `~~~` run at any indent (measured, `scratchpad/s277/reach`),
    // so this row is the only thing pinning it. Rendered firsthand on these exact bytes
    // (`scratchpad/s277/posit/s02_para_tilde_c0`, and `probes/pi04`): quarto emits BOTH headings.
    //
    // Pandoc's paragraph-interrupt power belongs to the BACKTICK fence alone — Session 200's
    // comment said so from one probe, and Session 277 measured it across ten rows (`truth/b1`
    // `para_ti_i0`, `b2` at run 4, with an info string, at four closer placements, `b6` in a
    // multi-line paragraph, `b5` in a knitr document). The blank-line control opens normally.
    expect(
      names(doc("prose line", "~~~", "", "## Charlie Tilde", "", "~~~text", "plain block",
                "~~~", "", "## Delta Tail", "", "tail")),
    ).toEqual(["h2:Charlie Tilde", "h2:Delta Tail"]); // quarto: both — measured, exit 0
  });

  it("RED->GREEN: a commonmark-family reader INVERTS the rule, so `from: gfm` keeps HEAD's swallow", () => {
    // ⚠ REFUSING HERE FABRICATES A HEADING, which is why the guard is part of the rule and not a
    // polish item. CommonMark §4.5 gives the fence its interrupt power at indent 0-3 and for
    // EITHER fence character, so under `gfm`, `commonmark` and `commonmark_x` quarto really does
    // open the region and swallow the heading. Rendered firsthand on these exact bytes
    // (`scratchpad/s277/posit/s04_gfm_bt_indent1`, and `freed/r01`-`r05`, `r09`, `r12`): quarto
    // emits ONLY the tail heading, and the unguarded build reported both on all seven probes.
    //
    // The gate is `commonmarkDialect` — `FRONTMATTER_COMMONMARK_FROM`, the set this model already
    // uses for the ATX closing run and the attribute grammar, reused rather than re-derived
    // (Learning #14). `markdown_strict`, `markdown_mmd` and `markdown-blank_before_header` do NOT
    // need it: they never interrupt at all, measured (`freed/r06`-`r08`), and stay as HEAD had
    // them. ⚠ A `from:` in a PROJECT file is invisible to this scanner by design, so such a
    // document keeps the default-dialect reading — the non-deleting direction.
    expect(
      names(doc("---", "from: gfm", "---", "", "prose line", " ```", "", "## Golf Gfm Indent One",
                "", "```text", "plain block", "```", "", "## Hotel Tail", "", "tail")),
    ).toEqual(["h2:Hotel Tail"]); // quarto: the tail only — measured, exit 0
  });

  it("RED->GREEN: an open CONTAINER suspends the rule, because a fence below a list item's column ENDS the item", () => {
    // ⚠ THE BOUNDARY THAT KEEPS THIS RULE SHIPPABLE, and it is measured on both sides.
    // Inside a list item a fence indented BELOW the item's content column does NOT stay in the
    // paragraph: it terminates the item and opens a REAL code region, for a backtick and for a
    // tilde alike. Rendered firsthand on these exact bytes (`scratchpad/s277/freed/h02`, and the
    // family `h05`-`h10`, `g20` — the `<pre><code>` read off the rendered HTML): quarto emits
    // ONLY the tail heading, and a build that refuses here reports the swallowed one as well.
    //
    // ⚠ The obvious container-relative rule — refuse at or beyond the innermost content column —
    // is MEASURED WORSE, not merely unproven: over 3,452 rendered probes the container-wide
    // variants scored 110 and 142 regressions against this rule's 10
    // (`scratchpad/s277/gate/all3.json`). What it needs first is a TIGHT-vs-LOOSE item
    // discriminator, because the same shape in a loose item, a footnote body, a definition body
    // or a table caption IS absorbed as paragraph text (`freed/h14`, `p03`, `p04`, `p08`, `g25`,
    // `p09`). That is filed, with its witnesses, in `BACKLOG.md`.
    expect(
      names(doc("- item text", " ```", "", "## Inside", "", "body", "", "```", "", "## After",
                "", "tail")),
    ).toEqual(["h2:After"]); // quarto: the tail only — measured, exit 0
  });
});

describe("GUARD — rows the paragraph-interrupt refusal may not touch (Session 277)", () => {
  const doc = (...lines: string[]) => lines.join("\n") + "\n";
  const names = (text: string) => findHeadings(text).map((h) => `h${h.level}:${h.text}`);

  it("a COLUMN-0 BACKTICK fence still interrupts, and that is the row a blanket bail would delete", () => {
    // Session 200 measured this and declined to guess the rest (`scratchpad/s200/par`,
    // `par_top_i00`; `twin/twin_i00`). Re-measured Session 277 on these exact bytes
    // (`scratchpad/s277/posit/s03_para_bt_c0_ctrl`, quarto exit 0): quarto emits ONLY the tail
    // heading — the region really does open and swallow the one above it.
    expect(
      names(doc("prose line", "```", "", "## Echo Column Zero", "", "```", "", "## Foxtrot Tail",
                "", "tail")),
    ).toEqual(["h2:Foxtrot Tail"]); // quarto: the tail only — measured, exit 0
    // Session 200's own control, unchanged by this session: a setext title below the closer.
    expect(
      names(doc("Intro paragraph.", "```", "code", "```", "Para Direct Title", "===")),
    ).toEqual(["h1:Para Direct Title"]); // quarto agrees exactly
  });

  it("a BLANK line above restores the ordinary 0-3 width, for both fence characters", () => {
    // THE CONTROL THAT MAKES THIS A PARAGRAPH RULE AND NOT AN INDENT RULE. The identical openers
    // the rows above refuse are ordinary fences here, because no paragraph is open
    // (`scratchpad/s277/truth/b1/blank_bt_i1`, `blank_ti_i0`, both rendered): quarto swallows.
    expect(
      names(doc("prose line", "", " ```", "", "## Swallowed", "", "```", "", "## Tail")),
    ).toEqual(["h2:Tail"]); // quarto: the tail only — measured, exit 0
    expect(
      names(doc("prose line", "", "~~~", "", "## Swallowed", "", "~~~", "", "## Tail")),
    ).toEqual(["h2:Tail"]); // quarto: the tail only — measured, exit 0
  });

  it("inside a BLOCK QUOTE the column is the quote's own, so a quoted tilde opener is refused", () => {
    // ⚠ A quote is NOT a `contentColumns` container here — the marker is stripped before the
    // fence test, so "column 0" means column 0 INSIDE the quote, and the rule fires there.
    // Measured (`scratchpad/s277/freed/h13_quote_tilde_c0`, `h12_quote_fence_c0`): quarto renders
    // the inner heading under a quoted `~~~` and swallows it under a quoted column-0 backtick.
    expect(
      names(doc("> prose line", "> ~~~", ">", "> ## Inside", ">", "> ~~~", "", "## After")),
    ).toEqual(["h2:Inside", "h2:After"]); // quarto: both — measured, exit 0
    expect(
      names(doc("> prose line", "> ```", ">", "> ## Inside", ">", "> ```", "", "## After")),
    ).toEqual(["h2:After"]); // quarto: the tail only — measured, exit 0
  });

  it("the CELL path is untouched: an indented cell opener still opens, divergence and all", () => {
    // ⚠ Only the PLAIN fence match is refused, so the line still falls through to
    // `indentedCellFenceAt` — quarto's own cell partitioner, which is paragraph-blind (S178).
    // This row asserts a KNOWN DIVERGENCE unchanged, not a correct answer: measured
    // (`scratchpad/s277/readers/Cj/j07_jup_cell_c1`, quarto exit 0) quarto renders BOTH headings
    // and this model reports only the tail, at HEAD and after this change alike. Filed in
    // `BACKLOG.md` with its sibling `c12_jup_cell_i4_free`, which needs no open paragraph at all.
    const cell = doc("prose", " ```{python}", "", "## A", "", "x = 1", "```", "", "## B", "", "tail");
    expect(findHeadings(cell, "jupyter").map((h) => `h${h.level}:${h.text}`)).toEqual(["h2:B"]);
  });

  it("RED->GREEN: a LAZY line below a block quote is not covered -- there the fence really does open", () => {
    // ⚠ FOUND BY THE ADVERSARIAL PASS BEFORE THIS SHIPPED, and it is a DELETION -- the direction
    // that matters. An UNMARKED line under a quoted paragraph is a lazy continuation, and pandoc
    // does NOT treat it the way it treats the paragraph's own lines: rendered firsthand
    // (`scratchpad/s277/q3b/t05_quote_lazy_indent1`, exit 0) quarto emits `h1:Tail`, so the
    // indent-1 opener DID open a code block there, and a build that refuses it loses the heading.
    //
    // ⚠ The MARKED twin is the opposite answer and is why this guard is about the marker, not
    // about quotes: with every line carrying `>` (`q3b/t02_quote_marked_all`) quarto emits NO
    // `h1:Tail` -- the fence does not interrupt -- and HEAD PHANTOMS it, which this rule fixes.
    // The mechanism was read off the rendered HTML, not inferred (`scratchpad/s277/q3/`): the
    // lazy lines are collected INTO the blockquote, where the fence opens a `<pre><code>` and the
    // heading below it is a real `<h1>` inside the quote.
    //
    // `stripQuote` is false on a lazy line (it requires a marker to strip), so without this
    // guard the line looks top-level. `quoteOpen` is the existing fail-safe that remembers a
    // quote may still be open -- reused rather than re-derived (Learning #14).
    expect(
      names(doc("> a quoted line of prose", " ```", "code body", " ```", "# Tail", "",
                "Trailing prose.", "", "## Anchor")),
    ).toEqual(["h1:Tail", "h2:Anchor"]); // quarto: both — measured, exit 0
  });

  it("RED->GREEN: a KNITR-claimed chunk interrupts at ANY indent, because knitr extracts it before pandoc", () => {
    // ⚠ ALSO FOUND BY THE ADVERSARIAL PASS. knitr's `chunk.begin` is a TEXTUAL scan that runs
    // before pandoc ever sees the file, so an indented chunk header is claimed whatever the
    // paragraph above it is doing, and quarto swallows the heading inside it. Rendered firsthand
    // as `.Rmd` with real knitr execution (`scratchpad/s277/adv-cells/k03_r2_i2.Rmd`,
    // `k04_myengine_i2.Rmd`, `n12_python3_i2_rmd.Rmd`, all exit 0): quarto emits ONLY
    // `h1:After Cell`, and refusing here reports the swallowed one as a phantom.
    //
    // ⚠ These info strings are knitr's class and NOT quarto's cell grammar (`CELL_INFO`), so
    // they do not take the `indentedCellFenceAt` path that already protects ```` ```{r} ````.
    // The predicate is `KNITR_CHUNK_INFO` — the Session 273 gate, reused, not re-derived.
    const chunk = doc("Paragraph line above the opener.", "  ```{r2}", "", "# Inside Cell", "",
                      "x <- 1", "  ```", "", "# After Cell");
    expect(findHeadings(chunk, "knitr").map((h) => `h${h.level}:${h.text}`)).toEqual([
      "h1:After Cell",
    ]); // quarto: the tail only — measured, .Rmd, real knitr, exit 0
    // CONTROL — the same bytes under the MARKDOWN engine, where knitr never runs: there the
    // indented opener is ordinary paragraph text and the heading survives (`adv-cells` twin).
    expect(findHeadings(chunk, "markdown").map((h) => `h${h.level}:${h.text}`)).toEqual([
      "h1:Inside Cell",
      "h1:After Cell",
    ]);
  });

  it("RED->GREEN: a refused opener still CONSUMES the closer it pairs with as an inline code span", () => {
    // ⚠ THE THIRD FINDING OF THE ADVERSARIAL PASS, and a DELETION again. With no blank line
    // between them the two backtick runs are ONE INLINE CODE SPAN inside the paragraph, so
    // NEITHER is a fence: rendered firsthand (`scratchpad/s277/adv-cells/j01_adj_i1_then_i0.qmd`,
    // exit 0) quarto emits BOTH headings. Refusing only the indented opener left the column-0
    // run below it live, and it then opened a region that swallowed `h1:After Pair`.
    //
    // Session 224 already built exactly this bookkeeping for the info-string refusal
    // (`consumedCloserLine` / `consumedFenceClosers`, and its blank-line asymmetry: with a blank
    // line the span cannot form and the closer really does become an opener). This rule joins
    // that same `refused` path rather than adding a second one — which is also why the
    // paragraph refusal is spelled as one more disjunct of `refused` and not as a null match.
    expect(
      names(doc("Paragraph line above.", " ```", "```", "", "# After Pair", "", "```", "",
                "# After Trailing")),
    ).toEqual(["h1:After Pair", "h1:After Trailing"]); // quarto: both — measured, exit 0
  });

  it("RED->GREEN: on a LAZY line the exemption is BACKTICK-ONLY -- a lazy tilde opener is still refused", () => {
    // ⚠ THE LAZY-LINE EXEMPTION ABOVE WAS TOO WIDE, and the adversarial pass caught the cost on
    // a row of Session 276's own corpus (`scratchpad/s276/adv2/verify-backtick-n1/mine/
    // V03_tilde_typo_quote_lazy.qmd`): refusing a tilde at top level freed the lazy tilde below a
    // quote to become an OPENER, and it swallowed a heading quarto renders. A refusal frees lines
    // (#586), and the freed line has to be read correctly too.
    //
    // So the lazy case was MEASURED rather than assumed, on an 8-probe matrix (two fence
    // characters x four indents, `scratchpad/s277/lazyq/`, every row rendered, exit 0): a lazy
    // BACKTICK opener OPENS at every indent 0-3 -- quarto emits `h1:Tail` -- and a lazy TILDE
    // opener NEVER opens, at any indent. The exemption therefore covers backticks only.
    // ⚠ This row also RETIRES A PRE-EXISTING PHANTOM: HEAD reported `h1:Tail` here.
    expect(
      names(doc("> a quoted line of prose", "~~~", "code body", "~~~", "# Tail", "",
                "Trailing prose.", "", "## Anchor")),
    ).toEqual(["h2:Anchor"]); // quarto: the anchor only — measured, exit 0
    // CONTROL -- the lazy BACKTICK twin, which quarto DOES open, is left alone (`lazyq/l_bt_i0`).
    expect(
      names(doc("> a quoted line of prose", "```", "code body", "```", "# Tail", "",
                "Trailing prose.", "", "## Anchor")),
    ).toEqual(["h1:Tail", "h2:Anchor"]); // quarto: both — measured, exit 0
  });

  it("RED->GREEN: an UNRESOLVABLE `from:` fails closed -- a YAML-anchored reader suspends the rule", () => {
    // ⚠ THE READER GUARD HAD A HOLE, found by the adversarial pass: `from: *r` with the reader
    // hidden behind a YAML ANCHOR is honoured by quarto and invisible to
    // `FRONTMATTER_COMMONMARK_FROM`, so `commonmarkDialect` stayed false and the rule fired where
    // CommonMark's interrupt really applies. Rendered firsthand (`scratchpad/s277/adv-reader/
    // b02_alias_nested_c1.qmd` and twelve siblings -- `e02` double-quoted, `e07` commonmark_x,
    // `e09` commonmark, `e10` with extensions, `e12` a block anchor, `e13` a sequence anchor):
    // quarto emits ONLY `h2:B`, and the rule reported `h2:A` as well.
    //
    // So the gate is now POSITIVE rather than negative -- it fires for the DEFAULT reader and for
    // the pandoc markdown family (`markdownFamilyDialect`, the existing flag), and abstains for
    // every `from:` this model cannot resolve. That is the same fail-closed direction the Session
    // 202 setext gate took for the same reason, and the non-deleting one here. ⚠ It is NOT a fix
    // for the alias itself: resolving anchors is a `FRONTMATTER_COMMONMARK_FROM` question shared
    // with the ATX and attribute rules, filed in `BACKLOG.md`, not widened here.
    expect(
      names(doc("---", "myreader: &r gfm", "format:", "  html:", "    from: *r", "---", "",
                "prose", " ```", "", "## A", "", "```text", "plain block", "```", "", "## B", "",
                "tail")),
    ).toEqual(["h2:B"]); // quarto: the tail only — measured, exit 0
  });
});

describe("a fence directly below an open LINE BLOCK is continuation text, not an opener (Session 280)", () => {
  const doc = (...lines: string[]) => lines.join("\n") + "\n";
  const names = (text: string) => findHeadings(text).map((h) => `h${h.level}:${h.text}`);

  it("RED->GREEN: a backtick opener INDENTED 1 directly below a line-block row is not a fence, so the heading below it survives", () => {
    // ⚠ THE DEFECT, and it is a heading DELETION. Rendered firsthand through the real `quarto
    // render` 1.7.33 on these exact bytes (`scratchpad/s277/freed/p10_lineblock_bt_c1`, re-rendered
    // Session 280 as `r1_bt_is_tight`): quarto emits BOTH headings, and HEAD reports only the
    // second. A line-block row's continuation attaches at ANY indent (`LINE_BLOCK_CONTINUATION`),
    // so the fence line is more row text -- the rendered `<div class="line-block">a line block
    // row ```</div>` -- and the blank line below it ends the block, leaving `## Inside` a heading.
    //
    // The model's `lineBlockOpen` leaves `paragraphOpen` FALSE (a line-block row is block-level),
    // so Session 277's `paragraphInterruptRefuses` never ran for it and the opener was accepted.
    expect(
      names(doc("| a line block row", " ```", "", "## Inside", "", "body text", "", "```", "",
                "## After", "", "tail")),
    ).toEqual(["h2:Inside", "h2:After"]); // quarto: both — measured, exit 0
  });

  it("RED->GREEN: a line block INSIDE a quote takes a MARKED continuation too, so a quoted indent-1 fence below it is text", () => {
    // ⚠ CORRECTED BY ITS OWN RE-MEASUREMENT. The first draft of this row asserted the opposite
    // ("quarto: the tail only") from a comparator that read heading ANCHOR IDs, and a heading
    // inside a block quote is rendered without one -- so the swallowed-looking heading was merely
    // invisible to the instrument. Re-read as heading TEXT off the rendered HTML (`scratchpad/s280`
    // `p2/q_marked.html`, quarto 1.7.33 exit 0): `<blockquote><div class="line-block">row
    // ```</div><h2>Inside</h2>...` -- both headings, the fence line is row text exactly as at top
    // level. A guard that withdrew the refusal for every MARKED line (`!stripQuote`) passed the
    // first draft and fails this one.
    expect(
      names(doc("> | row", ">  ```", ">", "> ## Inside", ">", "> body", ">", "> ```", "",
                "## After", "", "tail")),
    ).toEqual(["h2:Inside", "h2:After"]); // quarto: both — measured, exit 0
  });

  it("RED->GREEN: a commonmark-family reader has no line blocks, so `from: gfm` keeps HEAD's swallow", () => {
    // ⚠ THE SECOND PHANTOM THE UNGUARDED BUILD MADE. `line_blocks` is a pandoc-markdown
    // extension: `from: gfm` and `commonmark_x` read `| row` as an ordinary paragraph, and a
    // CommonMark fence interrupts a paragraph at indent 0-3, so the opener is real and swallows
    // the heading. Rendered firsthand on these exact bytes (`scratchpad/s280` `p2/rd_gfm`,
    // `rd_commonmark_x`, quarto 1.7.33 exit 0): quarto emits ONLY the tail heading.
    //
    // The gate is the one `paragraphInterruptRefuses` already takes -- `!dialectOverride ||
    // markdownFamilyDialect` -- reused, not re-derived (Learning #14). A `from:` this model
    // cannot resolve keeps the pandoc-markdown reading, the same fail-closed direction.
    expect(
      names(doc("---", "from: gfm", "---", "", "| a line block row", " ```", "", "## Inside", "",
                "body text", "", "```", "", "## After", "", "tail")),
    ).toEqual(["h2:After"]); // quarto: the tail only — measured, exit 0
  });
});

describe("REGRESSIONS found by Session 280's adversarial pass over the refusal above", () => {
  const doc = (...lines: string[]) => lines.join("\n") + "\n";
  const names = (text: string) => findHeadings(text).map((h) => `h${h.level}:${h.text}`);
  // ⚠ Each row was HEAD-correct and made WRONG by the first build of `lineBlockContinuationRefuses`;
  // a 6-lens, 31-agent adversary found 25 such documents and every one was re-rendered firsthand
  // (`scratchpad/s280/m/p4`, quarto 1.7.33 exit 0, HEAD agrees with quarto, the first build did not).

  it("RED->GREEN: a fence at a DIFFERENT quote depth than the line block is not its continuation", () => {
    // `scratchpad/s280/adv/quotes/a13_nested_outer_lb`: the line block lives two quotes deep and
    // the fence one deep, so it belongs to the OUTER quote, where it is an ordinary opener. The
    // first build compared only "quoted or not", never the depth.
    expect(
      names(doc("> > | row", ">  ```", "> > ## Inside", ">  ```", "", "## After")),
    ).toEqual(["h2:After"]); // quarto: the tail only — measured, exit 0
    // and the mirror (`a14_lb_outer_fence_inner`): block one deep, fence two deep
    expect(
      names(doc("> | row", "> >  ```", "> > ## Inside", "> >  ```", "", "## After")),
    ).toEqual(["h2:After"]); // quarto: the tail only — measured, exit 0
  });
  it("RED->GREEN: an UNMARKED line below a quoted line block is LAZY text of the quote, and a fence there opens", () => {
    // `scratchpad/s280/adv/quotes/b26_lazy_fence_heading_marked_close` and `b06_lazy_pipe_unmarked_
    // fence_after_marked_row`. Both render ONLY the tail: the unmarked indented fence is collected
    // into the quote's paragraph and opens there. In `b06` the unmarked `| row3` is itself a lazy
    // line, so it must not re-arm the line block as an UNQUOTED one -- the first build refused the
    // fence under it. The remembered quote (`quoteOpen`, Session 277's fail-safe) is what says a
    // quote may still be open, so an unmarked line abstains while one is.
    expect(
      names(doc("> | row", "  ```", ">", "> ## Inside", "  ```", "", "## After")),
    ).toEqual(["h2:After"]); // quarto: the tail only — measured, exit 0
    expect(
      names(doc("> | row", "> | row2", "| row3", "  ```", "## Inside", "  ```", "", "## After")),
    ).toEqual(["h2:After"]); // quarto: the tail only — measured, exit 0
  });
  it("RED->GREEN: a reader with NO line_blocks extension (strict, mmd, github, phpextra) keeps HEAD's answer", () => {
    // `scratchpad/s280/adv/realistic/f_from_markdown_strict` and its three siblings: quarto emits
    // `t,after` and the first build added `inside`. The gate was `markdownFamilyDialect`, which is
    // true of EVERY pandoc-markdown base, but `line_blocks` belongs to plain `markdown` alone --
    // `markdown_strict`, `markdown_mmd`, `markdown_github` and `markdown_phpextra` read `| line` as
    // a paragraph. The extension list is honoured (`markdown+line_blocks`, `markdown-line_blocks`),
    // last occurrence wins, through the same `fromExtensionState` the other extension rows use.
    for (const reader of ["markdown_strict", "markdown_mmd", "markdown_github", "markdown_phpextra"]) {
      expect(
        names(doc("---", `from: ${reader}`, "---", "", "# T", "", "| line", " ```", "## Inside",
                  " ```", "", "## After")),
      ).toEqual(["h1:T", "h2:After"]); // quarto: t,after — measured, exit 0
    }
  });
  it("RED->GREEN: a refused line-block fence does NOT swallow a later fence into an inline code span", () => {
    // `scratchpad/s280/adv/containers5/d03`, `d10`, `d11` and `containers6/e11`: the refused fence's
    // continuation ends at the ATX line below it, so no inline span can reach the next fence, which
    // is an ordinary opener. The first build ran `consumedCloserLine` on the refused opener anyway
    // (the Session 224 rule, true for a PARAGRAPH), withheld that fence, and the heading below the
    // run was then read as paragraph text and lost -- quarto renders it. HEAD kept `after` by
    // accident, because it opened the FIRST fence and lost `inside` instead.
    expect(
      names(doc("# Top", "", "| row", " ```", "## Inside", " ```", "code", " ```", "## After")),
    ).toEqual(["h1:Top", "h2:Inside", "h2:After"]); // quarto: all three — measured, exit 0 (d03)
    expect(
      names(doc("# Top", "", "| row", " ```", "## Inside", " ```", "| r", " ```", "## After")),
    ).toEqual(["h1:Top", "h2:Inside", "h2:After"]); // quarto: all three — measured, exit 0 (d10)
    expect(
      names(doc("# Top", "", "| row", " ```", "## Inside", "```", " ```", "## Hidden", "```", "## After")),
    ).toEqual(["h1:Top", "h2:Inside", "h2:Hidden"]); // quarto: these three — measured, exit 0 (e11)
  });
  it("RED->GREEN: an open LIST ITEM suspends the rule, because its fence is at the item's own column", () => {
    // `scratchpad/s280/adv2/containers2/B_t3`, `B_t5`, `R_ord_3` (round-2 adversary, each re-rendered
    // by a skeptic, exit 0): a list item directly below a line-block row opens a container, and a
    // fence at ITS content column is a real opener -- quarto swallows the heading inside it. The
    // refusal reported that heading. Session 277's rule suspends on `contentColumns` for the same
    // reason (a container-relative continuation needs its own discriminator, filed in BACKLOG.md).
    expect(
      names(doc("| row", " 1. item", "    ```", "    # Hin", "    ```", "", "# Hout", "", "text")),
    ).toEqual(["h1:Hout"]); // quarto: the outer heading only — measured, exit 0 (B_t3)
    expect(
      names(doc("| row", "  - item", "    ```", "    # Hin", "    ```", "", "# Hout", "", "text")),
    ).toEqual(["h1:Hout"]); // quarto: the outer heading only — measured, exit 0 (B_t5)
    expect(
      names(doc("| row", " 1. item", "    ~~~", "    # Hin", "    ~~~", "", "# Hout", "", "text")),
    ).toEqual(["h1:Hout"]); // quarto: the outer heading only — measured, exit 0 (R_ord_3)
  });
});

describe("GUARD — rows the line-block continuation refusal may not touch, and the siblings it covers (Session 280)", () => {
  const doc = (...lines: string[]) => lines.join("\n") + "\n";
  const names = (text: string) => findHeadings(text).map((h) => `h${h.level}:${h.text}`);
  // Every row below was rendered firsthand through quarto 1.7.33 (exit 0) on these exact bytes --
  // `scratchpad/s280` `p/` (54 documents) and `p2/` (24), re-read as heading TEXT off the rendered
  // HTML. ⚠ These are PINS written AFTER the rule, so most were GREEN on arrival: each one's job is
  // to fail if a clause of the rule is dropped, and the mutation pass that proves it is recorded
  // in `SESSION_NOTES.md`.
  const tail = (open: string, close: string) => ["", "## Inside", "", "body", "", close, "", "## After", "", "tail"].reduce<string[]>((a, l) => (a.push(l), a), [open]);

  it("covers the TILDE fence and every indent 1-3, with one row or a continued one", () => {
    expect(names(doc("| row", ...tail(" ~~~", "~~~")))).toEqual(["h2:Inside", "h2:After"]);
    expect(names(doc("| row", ...tail("   ```", "```")))).toEqual(["h2:Inside", "h2:After"]);
    expect(names(doc("| row", "  more", ...tail(" ~~~", "~~~")))).toEqual(["h2:Inside", "h2:After"]);
    expect(names(doc("| row one", "| row two", ...tail("  ~~~~", "~~~~")))).toEqual(["h2:Inside", "h2:After"]);
  });

  it("covers a fence WITH an info string, because the continuation owns the whole line", () => {
    expect(names(doc("| row", ...tail(" ```text", "```")))).toEqual(["h2:Inside", "h2:After"]);
    expect(names(doc("| row", ...tail(" ``` a`b", "```")))).toEqual(["h2:Inside", "h2:After"]);
  });

  it("a BLANK line between the row and the fence restores the ordinary opener", () => {
    expect(names(doc("| row", "", ...tail(" ```", "```")))).toEqual(["h2:After"]);
    expect(names(doc("| row one", "", "| row two", ...tail(" ```", "```")))).toEqual(["h2:Inside", "h2:After"]);
  });

  it("a COLUMN-0 fence ends the line block (no leading space, so no continuation) and still opens", () => {
    expect(names(doc("| row", ...tail("```", "```")))).toEqual(["h2:After"]);
    expect(names(doc("| row", ...tail("~~~", "~~~")))).toEqual(["h2:After"]);
  });

  it("a quote that OPENS below an unquoted line block is a fresh container, so its fence opens", () => {
    expect(names(doc("| row", ">  ```", ">", "> ## Inside", ">", "> ```", "", "## After")))
      .toEqual(["h2:After"]);
  });

  it("an UNMARKED line below a quoted line block keeps HEAD's answer -- a KNOWN DIVERGENCE, abstained on purpose", () => {
    // ⚠ NOT A CORRECT ANSWER. `> | row` / ` ```` (`scratchpad/s280` `p2/q_lazy`) renders BOTH headings
    // -- the lazy fence is continuation text -- while `b26` (`> | row` / `  ```` / `>` / `> ## Inside`)
    // renders only the tail, and nothing this model carries separates the two. The first build
    // refused both and was right on one and wrong on the other; abstaining is the non-regressing
    // direction, so this row asserts the swallow HEAD already had. Filed in `BACKLOG.md`.
    expect(names(doc("> | row", " ```", ...tail("", "```").slice(1)))).toEqual(["h2:After"]);
  });

  it("a pipe TABLE's body row is not a line block, so a fence below it still opens", () => {
    expect(names(doc("| a | b |", "|---|---|", "| 1 | 2 |", ...tail(" ```", "```")))).toEqual(["h2:After"]);
  });

  it("a reader WITHOUT line blocks keeps HEAD's answer, whatever quarto renders there", () => {
    // `commonmark_x` is a measured AGREEMENT (quarto: the tail only). `markdown-line_blocks` is a
    // KNOWN DIVERGENCE pinned, not a correct answer: quarto renders both headings (`p2/rd_markdown_
    // line_blocks`) and the rule abstains, because this model arms its line block there anyway and
    // the Session 277 paragraph rule never sees a paragraph. Filed in `BACKLOG.md`.
    expect(names(doc("---", "from: markdown-line_blocks", "---", "", "| row", ...tail(" ```", "```"))))
      .toEqual(["h2:After"]);
    expect(names(doc("---", "from: markdown+line_blocks", "---", "", "| row", ...tail(" ```", "```"))))
      .toEqual(["h2:Inside", "h2:After"]); // quarto: both — extension honoured
    expect(names(doc("---", "from: commonmark_x", "---", "", "| row", ...tail(" ```", "```"))))
      .toEqual(["h2:After"]); // quarto: the tail only — measured, exit 0
  });

  it("the CELL path is untouched: an indented cell opener below a line block still opens, divergence and all", () => {
    // KNOWN DIVERGENCE pinned, not a correct answer (`scratchpad/s280` `p/x_cell`): quarto renders
    // BOTH headings and this model reports only the tail, at HEAD and after this change alike --
    // the same standing divergence as Session 277's cell guard above, filed in `BACKLOG.md`.
    expect(findHeadings(doc("| row", ...tail(" ```{python}", "```")), "jupyter").map((h) => `h${h.level}:${h.text}`))
      .toEqual(["h2:After"]);
  });
});

